var employerManagerPendingToken = null; // token detected before employers loaded

// Seed editable content sections (FAQ, CV prep, etc.) with defaults if needed
if (window.ContentMgr) ContentMgr.ensureSeeded();

function genToken() {
  // 12-char URL-safe token
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  var s = '';
  for (var i = 0; i < 12; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}
function managerTokenKey(agencyId) { return 'sa_manager_token_' + agencyId; }
function getManagerToken(agencyId) {
  // Source of truth is Supabase (agenciesCache), so the token resolves on
  // any device, not just the one that generated it. Fall back to a local
  // cache copy only if the agency isn't in agenciesCache yet (e.g. called
  // before loadAll() finishes).
  var a = agenciesCache.find(function(x){ return x.id === agencyId; });
  if (a && a.manage_token) return a.manage_token;
  try { return localStorage.getItem(managerTokenKey(agencyId)) || ''; } catch(e){ return ''; }
}
function setManagerToken(agencyId, token) {
  // Update in-memory cache immediately so the UI reflects it right away
  var a = agenciesCache.find(function(x){ return x.id === agencyId; });
  if (a) a.manage_token = token;
  managerTokenMap[token] = agencyId;
  try { localStorage.setItem(managerTokenKey(agencyId), token); } catch(e){}
  // Persist to Supabase so the link works from any device
  saveManagerTokenToSupabase(agencyId, token);
}
function agencyIdFromToken(token) {
  if (!token) return null;
  // check cache first
  if (managerTokenMap[token]) return managerTokenMap[token];
  // Look up against Supabase-loaded agenciesCache (works cross-device)
  for (var i = 0; i < agenciesCache.length; i++) {
    if (agenciesCache[i].manage_token === token) {
      managerTokenMap[token] = agenciesCache[i].id;
      return agenciesCache[i].id;
    }
  }
  // Fallback: scan localStorage (covers agencies loaded before this fix
  // shipped, on the same browser that originally generated the token)
  for (var j = 0; j < agenciesCache.length; j++) {
    try {
      if (localStorage.getItem(managerTokenKey(agenciesCache[j].id)) === token) {
        managerTokenMap[token] = agenciesCache[j].id;
        return agenciesCache[j].id;
      }
    } catch(e){}
  }
  return null;
}
function buildManagerLink(token) {
  // Use the current app URL with ?manage=TOKEN
  var base = window.location.origin + window.location.pathname;
  return base + '?manage=' + token;
}

// ----- Employer manager tokens (mirrors the agency ones above, but keyed
// off the `employers` table and its own ?manage_employer=TOKEN param, so
// the two self-service links never collide) -----
function employerManagerTokenKey(employerId) { return 'sa_emp_manager_token_' + employerId; }
function getEmployerManagerToken(employerId) {
  var e = employersCache.find(function(x){ return x.id === employerId; });
  if (e && e.manage_token) return e.manage_token;
  try { return localStorage.getItem(employerManagerTokenKey(employerId)) || ''; } catch(e){ return ''; }
}
function setEmployerManagerToken(employerId, token) {
  var e = employersCache.find(function(x){ return x.id === employerId; });
  if (e) e.manage_token = token;
  employerManagerTokenMap[token] = employerId;
  try { localStorage.setItem(employerManagerTokenKey(employerId), token); } catch(e){}
  saveEmployerManagerTokenToSupabase(employerId, token);
}
async function saveEmployerManagerTokenToSupabase(employerId, token) {
  // Token writes are privileged (see supabase/migrations/20260918_lock_down_manager_tokens.sql):
  // signed-in admins go through the admin_set_employer_manager_token RPC; the
  // direct update below is a fallback for deployments where the authenticated
  // role still holds the column grant. Anonymous visitors cannot write tokens.
  try {
    var rpc = await supabaseClient.rpc('admin_set_employer_manager_token', { p_employer_id: employerId, p_token: token });
    if (!rpc.error && rpc.data === true) return;
  } catch(e) { /* fall through to the legacy path */ }
  try {
    var { error } = await supabaseClient.from('employers').update({ manage_token: token }).eq('id', employerId);
    if (error) {
      console.error('employer manage_token save', error);
      if (typeof showToast === 'function') showToast('⚠ Manager link not saved — generate links from the admin console (Regenerate ALL tokens).');
    }
  } catch(e) { console.error('employer manage_token save', e); }
}
function employerIdFromToken(token) {
  if (!token) return null;
  if (employerManagerTokenMap[token]) return employerManagerTokenMap[token];
  for (var i = 0; i < employersCache.length; i++) {
    if (employersCache[i].manage_token === token) {
      employerManagerTokenMap[token] = employersCache[i].id;
      return employersCache[i].id;
    }
  }
  for (var j = 0; j < employersCache.length; j++) {
    try {
      if (localStorage.getItem(employerManagerTokenKey(employersCache[j].id)) === token) {
        employerManagerTokenMap[token] = employersCache[j].id;
        return employersCache[j].id;
      }
    } catch(e){}
  }
  return null;
}
function buildEmployerManagerLink(token) {
  var base = window.location.origin + window.location.pathname;
  return base + '?manage_employer=' + token;
}

/* ── First-paint reveal: hides the splash AND the sign-in gate together,
   but only once CSS has loaded, the user is authenticated, AND real app
   content (cached or freshly loaded) has actually been rendered — then
   waits two animation frames so the browser has genuinely painted that
   content before starting the fade.

   Previously the splash and the sign-in gate hid independently of each
   other and of real paint completion (the gate in particular used a
   hard, transition-less display:none, fired the instant auth succeeded
   — before bootAuthenticatedApp() had rendered anything). That's what
   produced the visible flicker/jump: an overlay could disappear a frame
   or two before the content behind it had actually painted, briefly
   exposing an empty/half-loaded shell that then visibly popped in a
   moment later as data streamed in. ───────────────────────────────── */
var __saDataReady = false;
var __saAuthReady = false;
var __saRevealed = false;

function __saHideOverlayNow(el, removeFromDom) {
  if (!el) return;
  if (removeFromDom) { if (el.parentNode) el.parentNode.removeChild(el); }
  else { el.style.display = 'none'; }
}
function __saHideOverlayWithFade(el, removeFromDom) {
  if (!el || el.classList.contains('hide')) return;
  el.classList.add('hide');
  setTimeout(function () { __saHideOverlayNow(el, removeFromDom); }, 300);
}
function __saApplyReveal(usingViewTransition) {
  document.body.classList.add('app-ready');
  if (typeof __saClearSlowLoadStatus === 'function') __saClearSlowLoadStatus();
  var splash = document.getElementById('app-splash');
  var gate = document.getElementById('auth-gate');
  if (usingViewTransition) {
    // document.startViewTransition() already animates the before/after
    // states itself (a native cross-fade snapshot-to-snapshot), so the
    // overlays are removed outright here rather than also running our
    // own CSS opacity fade, which would otherwise double up the animation.
    __saHideOverlayNow(splash, true);
    __saHideOverlayNow(gate, false);
  } else {
    __saHideOverlayWithFade(splash, true);
    __saHideOverlayWithFade(gate, false);
  }
}
window.__saTryReveal = function () {
  // Guests are first-class: the reveal never waits for auth. __saAuthReady
  // only gates the signed-in data work (saved sync etc.), not the UI.
  if (__saRevealed || !__saDataReady || !window.__saCssReady) return;
  __saRevealed = true;
  // Two nested rAFs: the first runs once the browser has processed the
  // style/layout work from whatever just called this (e.g. the cards a
  // data load just rendered into the still-hidden .app); the second only
  // runs after that frame has actually been painted. Only then do we
  // start hiding the overlays, so neither the CSS fade nor the native
  // view-transition cross-fade can start before there's real, painted
  // content underneath them.
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      if (typeof document.startViewTransition === 'function') {
        document.startViewTransition(function () { __saApplyReveal(true); });
      } else {
        __saApplyReveal(false);
      }
    });
  });
};
function markAppDataReady() {
  __saDataReady = true;
  window.__saTryReveal();
}

/* ── Slow-load status text: stays invisible for the first SA_SLOW_LOAD_DELAY
   ms, so a normal, fast load never shows it. If the splash is still up
   after that delay, it fades in and cycles through short status messages
   with the three animated dots — reassurance that something is happening
   rather than the app being stuck. Cleared the moment the real reveal
   happens, wherever that fires from. ───────────────────────────────── */
var SA_SLOW_LOAD_DELAY = 1400; // ms before we admit the load is taking a while
var SA_SLOW_LOAD_MESSAGES = [
  { title: 'Getting things ready…', sub: 'Loading the latest listings' },
  { title: 'Almost there…', sub: 'Fetching vacancies and agency data' },
  { title: 'Just a moment…', sub: 'This is taking a little longer than usual' }
];
var __saSlowLoadTimer = null;
var __saSlowLoadCycleTimer = null;
var __saSlowLoadIndex = 0;

function __saCycleSlowLoadMessage() {
  var titleEl = document.getElementById('app-splash-title');
  var subEl = document.getElementById('app-splash-sub');
  if (!titleEl || !subEl) return;
  var msg = SA_SLOW_LOAD_MESSAGES[__saSlowLoadIndex % SA_SLOW_LOAD_MESSAGES.length];
  titleEl.textContent = msg.title;
  subEl.textContent = msg.sub;
  __saSlowLoadIndex++;
}
function __saShowSlowLoadStatus() {
  if (__saRevealed) return; // already loaded by the time the delay elapsed
  var status = document.getElementById('app-splash-status');
  if (!status) return;
  status.classList.add('show');
  __saCycleSlowLoadMessage();
  __saSlowLoadCycleTimer = setInterval(__saCycleSlowLoadMessage, 2200);
}
function __saClearSlowLoadStatus() {
  if (__saSlowLoadTimer) { clearTimeout(__saSlowLoadTimer); __saSlowLoadTimer = null; }
  if (__saSlowLoadCycleTimer) { clearInterval(__saSlowLoadCycleTimer); __saSlowLoadCycleTimer = null; }
}
__saSlowLoadTimer = setTimeout(__saShowSlowLoadStatus, SA_SLOW_LOAD_DELAY);
// Safety net: never leave the splash up more than 2.5s even if the
// stylesheet load event is somehow missed (slow network, browser quirk).
// Data may still be loading when this fires — the app paints whatever it
// has (cached shell or skeletons) and refreshes in place afterwards.
setTimeout(function () {
  window.__saCssReady = true;
  markAppDataReady();
}, 2500);

/* ── Theme (day / night) ───────────────────────────── */
function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  var meta = document.getElementById('meta-theme');
  if (meta) meta.setAttribute('content', theme === 'light' ? '#F2F2F7' : '#000000');
  // Update menu label/icon
  var mIcon = document.getElementById('theme-menu-icon');
  var mLabel = document.getElementById('theme-menu-label');
  var siteMenuThemeLabel = document.getElementById('site-menu-theme-label');
  /* Tile icons: CSS .profile-menu-item .mi-icon svg sets stroke:#fff, size, etc. */
  if (mIcon) mIcon.innerHTML = theme === 'light'
    ? '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2.5M12 19.5V22M4.2 4.2l1.8 1.8M18 18l1.8 1.8M2 12h2.5M19.5 12H22M4.2 19.8l1.8-1.8M18 6l1.8-1.8"/></svg>'
    : '<svg viewBox="0 0 24 24"><path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>';
  if (mLabel) {
    // Update only the title text node, preserving the .mi-sub subtitle
    var labelText = theme === 'light' ? 'Switch to night mode' : 'Switch to day mode';
    if (mLabel.firstChild && mLabel.firstChild.nodeType === 3) {
      mLabel.firstChild.nodeValue = labelText;
    } else {
      // Fallback: rebuild with subtitle
      mLabel.innerHTML = labelText + '<span class="mi-sub">Toggle between light &amp; dark appearance</span>';
    }
  }
  if (siteMenuThemeLabel) siteMenuThemeLabel.textContent = theme === 'light' ? 'Switch to night mode' : 'Switch to day mode';
}
function toggleTheme() {
  var current = document.documentElement.getAttribute('data-theme') || 'light';
  var next = current === 'dark' ? 'light' : 'dark';
  localStorage.setItem('saTheme', next);
  applyTheme(next);
}
(function initTheme() {
  var saved = localStorage.getItem('saTheme') || 'light';
  applyTheme(saved);
})();

function slugify(str) {
  return (str || '')
    .toString()
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
    .slice(0, 80) || 'listing';
}

function rebuildPublicListingSlugs() {
  publicAgencySlugs = Object.create(null);
  publicVacancySlugs = Object.create(null);
  publicVacancyRecordSlugs = typeof WeakMap === 'function' ? new WeakMap() : null;

  var agencyCounts = Object.create(null);
  agenciesCache.forEach(function(a) {
    var base = slugify(a.name);
    agencyCounts[base] = (agencyCounts[base] || 0) + 1;
  });
  agenciesCache.forEach(function(a) {
    var base = slugify(a.name);
    publicAgencySlugs[a.id] = agencyCounts[base] > 1
      ? base + '-' + String(a.id).slice(0, 6)
      : base;
  });

  var vacancyCounts = Object.create(null);
  var usedVacancySlugs = Object.create(null);
  vacanciesCache.forEach(function(v) {
    var base = slugify(v.title);
    vacancyCounts[base] = (vacancyCounts[base] || 0) + 1;
  });
  vacanciesCache.forEach(function(v, index) {
    var base = slugify(v.title);
    var hasStableId = v.id !== undefined && v.id !== null && v.id !== '';
    var slug = vacancyCounts[base] > 1 && hasStableId
      ? base + '-' + String(v.id).slice(0, 6)
      : (hasStableId ? base : base + '-row-' + index);
    if (usedVacancySlugs[slug]) slug = slug + '-row-' + index;
    usedVacancySlugs[slug] = true;
    if (hasStableId) publicVacancySlugs[v.id] = slug;
    if (publicVacancyRecordSlugs) publicVacancyRecordSlugs.set(v, slug);
  });
}
function publicAgencySlug(a) {
  return publicAgencySlugs[a && a.id] || slugify(a && a.name);
}
function publicVacancySlug(v) {
  return (v && publicVacancyRecordSlugs && publicVacancyRecordSlugs.get(v)) || publicVacancySlugs[v && v.id] || slugify(v && v.title);
}

function escapeHtml(s) {
  return String(s || '').replace(/[&<>"']/g, function(c) {
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c];
  });
}
function initials(n) {
  return (n || '?').trim().split(/\s+/).map(function(w){ return w[0]; }).join('').slice(0,2).toUpperCase();
}

;
/* ---- app-data.js ---- */
/*
 * SA Recruiters -- app.js split 2/8: app-data.js
 * Data layer: agencies, employers, branches, vacancies, app settings, daily track, local cache, loadAll()
 *
 * Part of the original monolithic app.js, mechanically split and kept as
 * classic (non-module) scripts loaded in this exact order via <script defer>
 * in index.html, so all functions/vars stay on one shared global scope
 * exactly as before. Do not reorder these files relative to one another.
 */

// ===== Data: AGENCIES (live Supabase table that works) =====
// SECURITY NOTE: manage_token is intentionally NOT selected here. The column
// is revoked from the anon role (see
// supabase/migrations/20260918_lock_down_manager_tokens.sql) so public reads
// can never leak Smart Manager links. Token resolution happens server-side
// via the Worker's /api/verify-manager endpoint (see app-manager.js).
async function getAgencies() {
  try {
    var { data, error } = await supabaseClient.from('agencies').select('id,name,website,contact,email,location,address,cvpref,photo,companies,trades,verified').order('created_at', { ascending: false });
    if (error) { console.error('agencies load', error); return markLoadError([]); }
    return data.map(function(a) { return { id: a.id, name: a.name, website: a.website, contact: a.contact, email: a.email, location: a.location, address: a.address, cvpref: a.cvpref, photo: a.photo, companies: a.companies, trades: a.trades, verified: !!a.verified, manage_token: '' }; });
  } catch(e) { console.error('agencies load', e); return markLoadError([]); }
}
// Persist a SMART MANAGER token so any device can resolve it (not just the
// browser that generated it). Token writes are privileged: signed-in admins
// go through the admin_set_manager_token RPC; the legacy direct update is
// kept as a fallback for deployments where the authenticated role still has
// the column grant. Anonymous visitors can no longer write tokens at all —
// that is the point of the lockdown migration.
async function saveManagerTokenToSupabase(agencyId, token) {
  try {
    var rpc = await supabaseClient.rpc('admin_set_manager_token', { p_agency_id: agencyId, p_token: token });
    if (!rpc.error && rpc.data === true) return;
  } catch(e) { /* fall through to the legacy path */ }
  try {
    var { error } = await supabaseClient.from('agencies').update({ manage_token: token }).eq('id', agencyId);
    if (error) {
      console.error('manage_token save', error);
      if (typeof showToast === 'function') showToast('⚠ Manager link not saved — generate links from the admin console (Regenerate ALL tokens).');
    }
  } catch(e) { console.error('manage_token save', e); }
}
async function upsertAgency(a) {
  // Send the FULL payload (including trades) to Supabase.
  // The `trades` column must exist on the agencies table — run
  // ADD_TRADES_COLUMN.sql once in the Supabase SQL Editor if it doesn't.
  // To stay resilient, if the upsert fails specifically because the
  // `trades` column is missing, we retry once without trades so the rest
  // of the agency record still saves (and trades keeps working via the
  // cached in-memory copy until the column is added).
  var safe = Object.assign({}, a);
  var { error } = await supabaseClient.from('agencies').upsert(safe);
  if (error) {
    var msg = (error.message || '') + ' ' + (error.hint || '') + ' ' + JSON.stringify(error.details || '');
    if (/trades/i.test(msg)) {
      // Column missing — retry without trades so the agency still saves.
      var safeNoTrades = Object.assign({}, a); delete safeNoTrades.trades;
      var r2 = await supabaseClient.from('agencies').upsert(safeNoTrades);
      if (r2.error) { console.error('agency save', r2.error); alert('Could not save. Check your Supabase setup.'); }
      else { console.warn('Saved agency, but the `trades` column is missing — run ADD_TRADES_COLUMN.sql so trades persist.'); }
      return;
    }
    console.error('agency save', error);
    alert('Could not save. Check your Supabase setup.');
  }
}
async function removeAgency(id) {
  var { error } = await supabaseClient.from('agencies').delete().eq('id', id);
  if (error) { console.error('agency delete', error); alert('Could not delete. Check your Supabase setup.'); }
}

/* ── Data: EMPLOYERS ──────────────────────────────────
   Companies that register directly and post their own vacancies (separate
   from the recruitment-agency directory). Same try-Supabase-then-fall-back
   pattern as branches/vacancies, so this works immediately even before the
   `employers` table + `employer_id` vacancies column are created — run
   CREATE_EMPLOYERS_TABLE.sql in the Supabase SQL Editor to make it live. */
async function getEmployers() {
  // manage_token is intentionally not selected — see the note on getAgencies().
  try {
    var { data, error } = await supabaseClient.from('employers').select('id,name,industry,website,contact,email,location,address,photo,verified').order('created_at', { ascending: false });
    if (!error && data) return data.map(function(e) { return { id: e.id, name: e.name, industry: e.industry, website: e.website, contact: e.contact, email: e.email, location: e.location, address: e.address, photo: e.photo, verified: !!e.verified, manage_token: '' }; });
  } catch(err){}
  return markLoadError(readLocal('employers'));
}
// ===== First-party house ads =====
var houseAdsCache = [];
function safeHouseAdUrl(value) {
  try {
    var url = new URL(String(value || ''), window.location.href);
    return /^https?:$/.test(url.protocol) ? url.href : '';
  } catch(e) { return ''; }
}
function houseAdPlacementMatches(ad, placement, slot) {
  var targets = Array.isArray(ad && ad.target_screens) ? ad.target_screens : null;
  var screenMatch = targets && targets.length ? targets.indexOf(placement) !== -1 : (ad && (ad.placement === placement || ad.placement === 'directories'));
  return !!ad && screenMatch && (ad.ad_slot || 'top') === slot;
}
function renderHouseAdSlot(targetId, placement, slot) {
  var target = document.getElementById(targetId);
  if (!target) return;
  var ad = (houseAdsCache || []).filter(function(item){ return houseAdPlacementMatches(item, placement, slot || 'top'); })[0];
  var imageUrl = ad && safeHouseAdUrl(ad.image_url);
  var targetUrl = ad && safeHouseAdUrl(ad.target_url);
  if (!ad || !imageUrl || !targetUrl) { target.hidden = true; target.innerHTML = ''; return; }
  target.hidden = false;
  var isRolazAd = /rolaz/i.test(String(ad.advertiser_name || '') + ' ' + String(ad.title || ''));
  var motionOverlay = isRolazAd ? '<span class="house-ad-bulb-glow" aria-hidden="true"></span><span class="house-ad-bulb-core" aria-hidden="true"></span><span class="house-ad-spark" aria-hidden="true"></span><span class="house-ad-tester-flicker" aria-hidden="true"></span>' : '';
  target.innerHTML = '<a class="house-ad-card" href="' + escapeHtml(targetUrl) + '" target="_blank" rel="noopener sponsored" onclick="trackHouseAdEvent(\'' + escapeHtml(ad.id) + '\',\'click\')">' +
    '<div class="house-ad-heading"><strong>' + escapeHtml(ad.title || ad.advertiser_name || '') + '</strong></div>' +
    '<div class="house-ad-creative">' +
      '<img loading="lazy" width="1200" height="400" src="' + escapeHtml(imageUrl) + '" alt="' + escapeHtml(ad.title || ad.advertiser_name || 'Sponsored promotion') + '" onerror="this.closest(\'.house-ad-slot\').hidden=true">' +
      motionOverlay +
    '</div>' +
    '<div class="house-ad-message"><small><span class="house-ad-message-copy">' + escapeHtml(ad.message || ((ad.title || ad.advertiser_name || '').toLowerCase().includes('rolaz') ? 'Keeping your home brighter' : '')) + '</span><span class="house-ad-sponsored">Sponsored</span></small></div>' +
  '</a>';
  trackHouseAdEvent(ad.id, 'impression');
}
function renderHouseAdSlots() {
  renderHouseAdSlot('house-ad-agencies-top', 'agencies', 'top');
  renderHouseAdSlot('house-ad-agencies-middle', 'agencies', 'middle');
  renderHouseAdSlot('house-ad-agencies-bottom', 'agencies', 'bottom');
  renderHouseAdSlot('house-ad-employers-top', 'employers', 'top');
  renderHouseAdSlot('house-ad-employers-middle', 'employers', 'middle');
  renderHouseAdSlot('house-ad-employers-bottom', 'employers', 'bottom');
  renderHouseAdSlot('house-ad-candidates-top', 'candidates', 'top');
  renderHouseAdSlot('house-ad-candidates-middle', 'candidates', 'middle');
  renderHouseAdSlot('house-ad-candidates-bottom', 'candidates', 'bottom');
  renderHouseAdSlot('house-ad-posters-top', 'posters', 'top');
  renderHouseAdSlot('house-ad-posters-middle', 'posters', 'middle');
  renderHouseAdSlot('house-ad-posters-bottom', 'posters', 'bottom');
}
async function loadHouseAds() {
  try {
    var now = new Date().toISOString();
    var result = await supabaseClient.from('house_ads').select('id,advertiser_name,title,message,image_url,target_url,placement,target_screens,ad_slot,starts_at,ends_at,sort_order').eq('is_active', true).lte('starts_at', now).or('ends_at.is.null,ends_at.gt.' + now).order('sort_order', { ascending: true }).order('created_at', { ascending: false }).limit(20);
    if (result.error) throw result.error;
    houseAdsCache = result.data || [];
    renderHouseAdSlots();
  } catch(e) { console.warn('house ads load', e); }
}
function trackHouseAdEvent(id, eventName) {
  if (!id || !supabaseClient || ['impression','click'].indexOf(eventName) === -1) return;
  var key = 'sa_house_ad_' + eventName + '_' + id;
  if (eventName === 'impression') {
    try { if (sessionStorage.getItem(key) === '1') return; sessionStorage.setItem(key, '1'); } catch(e) {}
  }
  supabaseClient.rpc('record_house_ad_event', { p_ad_id: id, p_event: eventName }).then(function(result){ if (result.error) console.warn('house ad tracking', result.error); });
}

async function getManagedPosters() {
  try {
    var { data, error } = await supabaseClient.from('posters').select('id,audience,title,subtitle,image_url,sort_order').eq('is_active', true).order('audience', { ascending: true }).order('sort_order', { ascending: true }).order('created_at', { ascending: false });
    if (!error) return data || [];
    console.warn('managed posters load', error);
  } catch (e) { console.warn('managed posters load', e); }
  return [];
}
function renderManagedPoster(poster, targetId) {
  var target = document.getElementById(targetId);
  if (!target) return;
  if (!poster || !poster.image_url) { target.hidden = true; target.innerHTML = ''; return; }
  target.hidden = false;
  target.innerHTML = '<img loading="lazy" src="'+escapeHtml(poster.image_url)+'" alt="'+escapeHtml(poster.title || '')+'" onerror="this.closest(\'.managed-poster\').hidden=true">' +
    ((poster.title || poster.subtitle) ? '<div class="managed-poster-copy">'+(poster.title?'<strong>'+escapeHtml(poster.title)+'</strong>':'')+(poster.subtitle?'<span>'+escapeHtml(poster.subtitle)+'</span>':'')+'</div>' : '');
}
function renderManagedPosters(posters) {
  var target = document.getElementById('poster-managed-poster');
  if (!target) return;
  posters = (posters || []).filter(function(p){ return p && p.image_url; });
  if (!posters.length) {
    target.innerHTML = '<div class="poster-empty">Campaign posters will appear here soon.</div>';
    return;
  }
  // The page intentionally displays one poster at a time. Admin ordering controls
  // which active poster is shown, while the fixed frame prevents layout shifts.
  var p = posters[0];
  var label = p.audience === 'employers' ? 'For Employers' : 'For Candidates';
  target.innerHTML = '<article class="managed-poster poster-page-card"><img loading="lazy" src="'+escapeHtml(p.image_url)+'" alt="'+escapeHtml(p.title || label+' campaign poster')+'" onerror="this.closest(\'.poster-page-card\').remove()">'+
    '<div class="managed-poster-copy"><strong>'+escapeHtml(p.title || label)+'</strong>'+(p.subtitle?'<span>'+escapeHtml(p.subtitle)+'</span>':'')+'</div></article>';
}

// ===== HOME SCREEN CANDIDATE SPOTLIGHT =====
// Advertises real Talent Pool candidates on the home CTA carousel: their
// square profile photo, name, and position/experience heading. Pulled
// straight from pool_candidates (no separate admin upload needed) —
// tapping a card sends the visitor to the full Talent Pool for the
// complete Mini-CV. RLS only ever returns status = 'active' rows to
// anonymous visitors, but the status filter below is defense-in-depth.
var publicPoolStartupPromise = null;
async function getPublicPoolCandidatesFromWorker() {
  if (window.__saStartupPayload && Array.isArray(window.__saStartupPayload.pool_candidates)) {
    return window.__saStartupPayload;
  }
  if (!publicPoolStartupPromise) {
    publicPoolStartupPromise = fetch(R2_WORKER_URL + '/api/startup', {
      method: 'GET', cache: 'no-store', headers: { Accept: 'application/json' }
    }).then(function(response) {
      if (!response.ok) throw new Error('Talent Pool Worker request failed');
      return response.json();
    });
  }
  try {
    return await publicPoolStartupPromise;
  } catch (e) {
    publicPoolStartupPromise = null;
    return null;
  }
}
async function loadCandidateSpotlight() {
  var target = document.getElementById('candidate-spotlight-deck');
  if (!target) return;
  var list = [];
  try {
    var startup = await getPublicPoolCandidatesFromWorker();
    if (startup && Array.isArray(startup.pool_candidates)) {
      list = startup.pool_candidates.filter(function(c){ return (c.status || 'pending') === 'active'; }).slice(0, 30);
    } else {
      // Resilience fallback for a temporary Worker/D1 outage.
      var result = await supabaseClient.from('pool_candidates_public')
        .select('id,full_name,position,sector,location,experience_years,about_you,photo_url,verified,status,created_at')
        .order('created_at', { ascending: false }).limit(30);
      if (result.error) throw result.error;
      list = (result.data || []).filter(function(c){ return (c.status || 'pending') === 'active'; });
    }
  } catch (e) { console.warn('candidate spotlight load', e); list = []; }
  // Keep complete profiles ahead of partial profiles. A profile is considered
  // complete for the public spotlight when its useful professional summary is
  // present: name, position, sector, location, experience and about text.
  // Photo is intentionally optional and does not make a candidate look
  // incomplete. Verified status remains the tie-breaker within each group.
  function spotlightCompleteness(c) {
    var score = 0;
    if (String(c.full_name || '').trim()) score++;
    if (String(c.position || '').trim()) score++;
    if (String(c.sector || '').trim()) score++;
    if (String(c.location || '').trim()) score++;
    if (c.experience_years !== null && c.experience_years !== undefined && c.experience_years !== '') score++;
    if (String(c.about_you || '').trim()) score++;
    return score;
  }
  list.sort(function(a, b) {
    var aScore = spotlightCompleteness(a), bScore = spotlightCompleteness(b);
    var aComplete = aScore === 6, bComplete = bScore === 6;
    if (aComplete !== bComplete) return aComplete ? -1 : 1;
    if (aScore !== bScore) return bScore - aScore;
    if ((b.verified?1:0) !== (a.verified?1:0)) return (b.verified?1:0) - (a.verified?1:0);
    return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
  });
  renderCandidateSpotlight(list.slice(0, 10));
}
function renderCandidateSpotlight(list) {
  var target = document.getElementById('candidate-spotlight-deck');
  if (!target) return;
  if (!list.length) {
    target.innerHTML = '<div class="poster-empty">Candidates will appear here as people join the Talent Pool.</div>';
    return;
  }
  target.innerHTML = list.map(function(c) {
    var expText = (c.experience_years !== null && c.experience_years !== undefined && c.experience_years !== '')
      ? (c.experience_years >= 10 ? '10+ yrs exp' : c.experience_years + ' yrs exp')
      : '';
    var subtitle = [c.position, expText].filter(Boolean).join(' · ') || 'Looking for opportunities';
    return '<button type="button" class="spotlight-card" data-ripple onclick="goPool(\'profile\',\''+escapeHtml(c.id)+'\')">' +
      (c.photo_url ? '<span class="spotlight-photo"><img loading="lazy" src="'+escapeHtml(c.photo_url)+'" alt="'+escapeHtml(c.full_name||'Candidate')+'"></span>' : '<span class="spotlight-photo spotlight-initials">'+initials(c.full_name)+'</span>') +
      '<span class="spotlight-copy"><strong>'+escapeHtml(c.full_name||'Candidate')+(c.verified?' ' + verifiedBadge('Screened &amp; Verified') + '':'')+'</strong>' +
      '<span>'+escapeHtml(subtitle)+'</span></span></button>';
  }).join('') + '<button type="button" class="spotlight-card spotlight-more" data-ripple onclick="goPool(\'profile\')"><span class="spotlight-more-copy">View full<br>Talent Pool</span></button>';
}

async function upsertEmployer(e) {
  try {
    var { error } = await supabaseClient.from('employers').upsert(e);
    if (!error) return true;
  } catch(err){}
  var arr = readLocal('employers');
  var i = arr.findIndex(function(x){ return x.id === e.id; });
  if (i >= 0) arr[i] = Object.assign({}, arr[i], e); else arr.push(e);
  writeLocal('employers', arr);
  return false;
}
async function removeEmployer(id) {
  try { await supabaseClient.from('employers').delete().eq('id', id); } catch(err){}
  var arr = readLocal('employers').filter(function(x){ return x.id !== id; });
  writeLocal('employers', arr);
}

/* ── Data: BRANCHES & VACANCIES ─────────────────────────
   The `branches` table now EXISTS in Supabase (verified).
   The `vacancies` table was NOT yet created — run CREATE_VACANCIES_TABLE.sql
   in the Supabase SQL Editor, otherwise every vacancy save silently falls
   back to THIS device's localStorage and other users will not see it.
   To keep the features fully functional in the meantime we:
     1) TRY to read/write Supabase (so the moment the table exists it works)
     2) FALL BACK to localStorage so nothing is ever lost and the UX works.
   When a save is NOT live, saveVacancy()/saveGeneralVacancy() now show a
   clear warning toast.                                              */
function localKey(kind) { return 'sa_' + kind + '_local'; }
function readLocal(kind) {
  try { return JSON.parse(localStorage.getItem(localKey(kind)) || '[]'); } catch(e){ return []; }
}
function writeLocal(kind, arr) {
  try { localStorage.setItem(localKey(kind), JSON.stringify(arr)); } catch(e){ console.warn('storage full', e); }
}

// ----- Branches -----
async function getBranches() {
  try {
    var { data, error } = await supabaseClient.from('branches').select('id,agency_id,name,location,phone,email').order('name', { ascending: true });
    if (!error && data) return data;
  } catch(e){}
  return markLoadError(readLocal('branches'));
}
async function upsertBranch(b) {
  try {
    var { error } = await supabaseClient.from('branches').upsert(b);
    if (!error) return true;
  } catch(e){}
  // fallback: save locally
  var arr = readLocal('branches');
  var i = arr.findIndex(function(x){ return x.id === b.id; });
  if (i >= 0) arr[i] = Object.assign({}, arr[i], b); else arr.push(b);
  writeLocal('branches', arr);
  return false; // indicates it was stored locally, not in Supabase
}
async function removeBranch(id) {
  try { await supabaseClient.from('branches').delete().eq('id', id); } catch(e){}
  var arr = readLocal('branches').filter(function(x){ return x.id !== id; });
  writeLocal('branches', arr);
}

